17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.server.ResponseStatusException;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        HttpHeaders headers = new HttpHeaders();
104	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
105	        String normalizedAddress = normalizeAddress(owner.getAddress());
106	        if (normalizedAddress.isEmpty()) {
107	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
108	                "Address must not be blank after normalization");
109	        }
110	        owner.setAddress(normalizedAddress);
111	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
112	        owner.setTelephone(normalizedTelephone);
113	        owner.setEmail(normalizeEmail(owner.getEmail()));
114	        if (owner.getRegistrationDate() == null) {
115	            owner.setRegistrationDate(java.time.LocalDate.now());
116	        }
117	        java.time.LocalDate today = java.time.LocalDate.now();
118	        long createdToday = this.clinicService.findAllOwners().stream()
119	            .map(Owner::getRegistrationDate)
120	            .filter(today::equals)
121	            .count();
122	        if (createdToday >= 100) {
123	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
124	                "The maximum number of owners for today has already been reached");
125	        }
126	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
127	            .map(Owner::getTelephone)
128	            .filter(java.util.Objects::nonNull)
129	            .anyMatch(normalizedTelephone::equals);
130	        if (telephoneInUse) {
131	            throw new ResponseStatusException(HttpStatus.CONFLICT,
132	                "An owner with this telephone number already exists");
133	        }
134	        String lastNameKey = normalizeForHousehold(owner.getLastName());
135	        String addressKey = normalizeForHousehold(owner.getAddress());
136	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
137	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(lastNameKey)
138	                && normalizeForHousehold(existing.getAddress()).equals(addressKey))
139	            .toList();
140	        if (!householdMembers.isEmpty()) {
141	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
142	                throw new ResponseStatusException(HttpStatus.CONFLICT,
143	                    "An owner with this last name already exists at this address");
144	            }
145	            String householdId = householdId(lastNameKey, addressKey);
146	            owner.setHouseholdId(householdId);
147	            for (Owner member : householdMembers) {
148	                if (!householdId.equals(member.getHouseholdId())) {
149	                    member.setHouseholdId(householdId);
150	                    this.clinicService.saveOwner(member);
151	                }
152	            }
153	        }
154	        String cityKey = normalizeForHousehold(owner.getCity());
155	        long cityCount = this.clinicService.findAllOwners().stream()
156	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
157	            .count();
158	        if (cityCount >= 50) {
159	            throw new ResponseStatusException(HttpStatus.CONFLICT,
160	                "This city already has the maximum number of owners");
161	        }
162	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
163	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
164	        this.clinicService.saveOwner(owner);
165	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
166	        headers.setLocation(UriComponentsBuilder.newInstance()
167	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
168	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
169	    }
170	
171	    /**
172	     * Counts the owners that already exist (before the current create) whose first and last names
173	     * both match the supplied names, compared case-insensitively. The returned value is captured on
174	     * the new owner at creation time and does not change as further owners are added later.
175	     *
176	     * @param firstName the new owner's first name
177	     * @param lastName  the new owner's last name
178	     * @return the number of pre-existing namesake owners
179	     */
180	    private int namesakeCount(String firstName, String lastName) {
181	        return (int) this.clinicService.findAllOwners().stream()
182	            .filter(existing -> existing.getFirstName() != null
183	                && existing.getFirstName().equalsIgnoreCase(firstName)
184	                && existing.getLastName() != null
185	                && existing.getLastName().equalsIgnoreCase(lastName))
186	            .count();
187	    }
188	
189	    /**
190	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where
191	     * {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3} is the
192	     * upper-cased first three letters of the last name, and {@code NNNN} is a per-city 4-digit
193	     * zero-padded sequence equal to one more than the number of owners already in that city
194	     * (e.g. {@code 'SYD-SMI-0007'}).
195	     *
196	     * @param city     the owner's city
197	     * @param lastName the owner's last name
198	     * @return the assigned customer code
199	     */
200	    private String nextCustomerCode(String city, String lastName) {
201	        String cityPrefix = first3Upper(city);
202	        String lastPrefix = first3Upper(lastName);
203	        String cityKey = normalizeForHousehold(city);
204	        long sequence = this.clinicService.findAllOwners().stream()
205	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
206	            .count() + 1L;
207	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
208	    }
209	
210	    /**
211	     * Returns the upper-cased first three characters of {@code value}, or fewer if the value is
212	     * shorter. A {@code null} value yields the empty string.
213	     *
214	     * @param value the source value
215	     * @return the upper-cased first three characters
216	     */
217	    private String first3Upper(String value) {
218	        String v = (value == null ? "" : value);
219	        return v.substring(0, Math.min(3, v.length())).toUpperCase(java.util.Locale.ROOT);
220	    }
221	
222	    /**
223	     * Normalizes a street address applied whenever an owner is created: leading and trailing
224	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
225	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
226	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
227	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
228	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
229	     * {@code '12 MAIN STREET'}.
230	     *
231	     * @param address the raw address as submitted, or {@code null} when absent
232	     * @return the normalized address, or the empty string when the value is blank
233	     */
234	    private String normalizeAddress(String address) {
235	        String collapsed = (address == null ? "" : address)
236	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
237	        if (collapsed.isEmpty()) {
238	            return "";
239	        }
240	        String[] tokens = collapsed.split(" ");
241	        for (int i = 0; i < tokens.length; i++) {
242	            switch (tokens[i]) {
243	                case "ST" -> tokens[i] = "STREET";
244	                case "RD" -> tokens[i] = "ROAD";
245	                case "AVE" -> tokens[i] = "AVENUE";
246	                default -> { }
247	            }
248	        }
249	        return String.join(" ", tokens);
250	    }
251	
252	    /**
253	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
254	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
255	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
256	     * empty string.
257	     *
258	     * @param value the raw value (last name or address) as submitted
259	     * @return the normalized comparison key
260	     */
261	    private String normalizeForHousehold(String value) {
262	        if (value == null) {
263	            return "";
264	        }
265	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
266	    }
267	
268	    /**
269	     * Derives the stable shared household identifier for a household, keyed on the normalized last
270	     * name and address. Because it is a pure function of those normalized keys, every owner in the
271	     * same household deterministically computes the same value. The identifier is the first 12
272	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
273	     * (the separator prevents distinct name/address pairs from colliding).
274	     *
275	     * @param lastNameKey the normalized last-name comparison key
276	     * @param addressKey  the normalized address comparison key
277	     * @return the stable household identifier
278	     */
279	    private String householdId(String lastNameKey, String addressKey) {
280	        String seed = lastNameKey + "�" + addressKey;
281	        try {
282	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
283	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
284	            StringBuilder sb = new StringBuilder(digest.length * 2);
285	            for (byte b : digest) {
286	                sb.append(String.format("%02x", b));
287	            }
288	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
289	        }
290	        catch (java.security.NoSuchAlgorithmException e) {
291	            throw new IllegalStateException("SHA-256 not available", e);
292	        }
293	    }
294	
295	    /**
296	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
297	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
298	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
299	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
300	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
301	     * is stored as {@code '+61412345678'}.
302	     *
303	     * @param telephone the raw telephone number as submitted
304	     * @return the normalized E.164 telephone number
305	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
306	     *         number (8 to 15 digits after the '+')
307	     */
308	    private String normalizeTelephone(String telephone) {
309	        String raw = telephone == null ? "" : telephone.trim();
310	        String digits = raw.replaceAll("\\D", "");
311	        String e164;
312	        if (raw.startsWith("+")) {
313	            e164 = "+" + digits;
314	        } else {
315	            if (digits.startsWith("0")) {
316	                digits = digits.substring(1);
317	            }
318	            e164 = "+61" + digits;
319	        }
320	        int digitCount = e164.length() - 1;
321	        if (digitCount < 8 || digitCount > 15) {
322	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
323	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
324	        }
325	        return e164;
326	    }
327	
328	    /**
329	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
330	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
331	     * (absent) or already valid.
332	     *
333	     * @param email the email address as submitted, or {@code null} when absent
334	     * @return the lower-cased email, or {@code null} when absent
335	     */
336	    private String normalizeEmail(String email) {
337	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
338	    }
339	
340	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
341	    @Override
342	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
343	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
344	        if (currentOwner == null) {
345	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
346	        }
347	        currentOwner.setAddress(ownerFieldsDto.getAddress());
348	        currentOwner.setCity(ownerFieldsDto.getCity());
349	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
350	        currentOwner.setLastName(ownerFieldsDto.getLastName());
351	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
352	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
353	        this.clinicService.saveOwner(currentOwner);
354	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
355	    }
356	
357	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
358	    @Transactional
359	    @Override
360	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
361	        Owner owner = this.clinicService.findOwnerById(ownerId);
362	        if (owner == null) {
363	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
364	        }
365	        this.clinicService.deleteOwner(owner);
366	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
367	    }
368	
369	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
370	    @Override
371	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
372	        Owner owner = this.clinicService.findOwnerById(ownerId);
373	        if (owner == null) {
374	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
375	        }
376	        HttpHeaders headers = new HttpHeaders();
377	        Pet pet = petMapper.toPet(petFieldsDto);
378	        owner.setId(ownerId);
379	        pet.setOwner(owner);
380	        pet.getType().setName(null);
381	        this.clinicService.savePet(pet);
382	        PetDto petDto = petMapper.toPetDto(pet);
383	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
384	            .buildAndExpand(pet.getId()).toUri());
385	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
386	    }
387	
388	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
389	    @Override
390	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
391	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
392	        if (currentOwner != null) {
393	            Pet currentPet = this.clinicService.findPetById(petId);
394	            if (currentPet != null) {
395	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
396	                currentPet.setName(petFieldsDto.getName());
397	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
398	                this.clinicService.savePet(currentPet);
399	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
400	            }
401	        }
402	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
403	    }
404	
405	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
406	    @Override
407	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
408	        HttpHeaders headers = new HttpHeaders();
409	        Visit visit = visitMapper.toVisit(visitFieldsDto);
410	        Pet pet = new Pet();
411	        pet.setId(petId);
412	        visit.setPet(pet);
413	        this.clinicService.saveVisit(visit);
414	        VisitDto visitDto = visitMapper.toVisitDto(visit);
415	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
416	            .buildAndExpand(visit.getId()).toUri());
417	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
418	    }
419	
420	
421	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
422	    @Override
423	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
424	        Owner owner = this.clinicService.findOwnerById(ownerId);
425	        if (owner != null) {
426	            Pet pet = owner.getPet(petId);
427	            if (pet != null) {
428	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
429	            }
430	        }
431	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
432	    }
433	}
